const COLUMNS: Record<string, Record<number, { title: string; body: string; a8: { name: string; url: string; desc: string; amazon?: boolean; serviceSlug?: string; deepColumnUrl?: string; imgUrl?: string; imgWidth?: number; imgHeight?: number; impUrl?: string }[] }>> = {
  'hajimete': {
    1: { title: "実家をどうするか迷ったらまず読む記事", body: "「実家をどうしよう」と漠然と悩んでいる方は多いはずです。親が高齢になり、いつかは空き家になるかもしれない。でも、何から考えればいいのかわからない。そんな方のために、まず「選択肢の整理」から始めましょう。\n\n実家の扱い方には大きく4つの選択肢があります。①売却（まとまった現金を得られる）、②賃貸（毎月の収入が入る）、③活用（リノベやシェアハウスなど）、④そのまま管理（家族が住む・空き家として維持）です。\n\nどれが正解かは、家族の状況・家の状態・立地・財産状況によって変わります。大切なのは「なんとなく放置」ではなく、意識的に選択することです。まずは家族で話し合う場を作り、それぞれの希望をすり合わせることが第一歩になります。\n\n診断を受けると、あなたの状況に合った選択肢が10問で見えてきます。ぜひ試してみてください。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    2: { title: "親が高齢になったら考えること", body: "親が70代・80代になったとき、子供として何を考えればいいのでしょうか。「まだ元気だから大丈夫」と思っていても、認知症や介護が突然始まることがあります。手遅れになる前に、3つのテーマを話し合っておきましょう。\n\n1つ目は「実家」です。誰が住むのか、老後どうするのか、売却や賃貸の可能性はあるのかを確認しておきます。2つ目は「介護」です。在宅か施設か、誰が面倒をみるのかを家族間で共有しておくことが重要です。3つ目は「相続」です。遺言書があるか、財産の内訳はどうなっているかを早めに把握しておきましょう。\n\nこれらの話題は「縁起でもない」と避けがちですが、事前に話し合っておくことで、いざというときに家族がもめることなく動けます。親が元気なうちこそ、穏やかに話し合えるチャンスです。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    3: { title: "実家の名義・権利関係を確認する方法", body: "実家の名義が誰になっているか、あなたはすぐに答えられますか？意外と知らないまま時間が過ぎ、相続のときに初めて「共有名義だった」と気づくケースが多くあります。\n\n名義の確認は法務局で「登記事項証明書（登記簿謄本）」を取得することで行えます。最近はオンライン申請も可能で、数百円の手数料で取得できます。確認すべきポイントは「所有者は誰か」「抵当権（ローン）は残っているか」「共有名義になっていないか」の3点です。\n\n共有名義の場合、売却には全員の同意が必要になります。兄弟の誰かが行方不明・認知症・死亡している場合は手続きが大変複雑になります。早めに確認し、必要なら名義整理を行うことが後々のトラブル防止につながります。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    4: { title: "実家の固定資産税を確認する方法", body: "実家を所有し続ける限り、毎年「固定資産税」がかかります。住んでいないのに税金だけ払い続けるのはもったいない、と感じる方も多いでしょう。まずは現状の税額を確認することから始めましょう。\n\n固定資産税は毎年4〜6月頃に「固定資産税・都市計画税納税通知書」が届きます。税額は土地と建物それぞれの固定資産税評価額に税率（標準1.4%）をかけて計算されます。\n\n注意が必要なのは空き家特措法による優遇廃止です。住宅用地には固定資産税の軽減措置（6分の1）がありますが、特定空き家に指定されると優遇が取り消され、税額が最大6倍になることがあります。実家の税額を把握し、維持コストを計算したうえで今後の方針を決めましょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    5: { title: "実家を将来どうするか家族会議の進め方", body: "「実家の話をしようとすると、家族でもめる」という方は少なくありません。それぞれの思い入れや立場が違うため、感情的になりやすいテーマです。しかし、話し合いを先延ばしにすることが最も危険です。\n\n家族会議をうまく進めるには「誰かが一人で決める」のではなく「全員で情報共有する場」として設定しましょう。議題は「実家をどうするか」ではなく「現状の把握と選択肢の確認」に留めるのがスムーズです。\n\n事前に準備しておくと良いものは、登記簿謄本・固定資産税の納税通知書・ローン残高の確認書類などです。不動産の専門家やFPに同席してもらうことで、感情論ではなく事実ベースで話し合いが進みやすくなります。まずは「情報を共有する場」を作ることが第一歩です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    6: { title: "実家の片付け・生前整理の進め方", body: "実家の荷物の多さに圧倒されて、片付けに手が付けられないという方は多いです。しかし片付けは早く始めるほど負担が少なくなります。親が元気なうちに一緒に行う「生前整理」が理想的です。\n\n片付けを進める順番は「使わないもの→思い出の品→貴重品・書類」の順がおすすめです。いきなり思い出の品に手をつけると作業が止まりがちです。まずは明らかに不要なものから始めて達成感を積み重ねましょう。\n\nプロの遺品整理・生前整理業者に依頼する方法もあります。費用は家の広さや荷物の量によりますが、1LDKで5〜20万円程度が目安です。業者によっては買取もしてくれるため、費用の一部が相殺されることもあります。実家の片付けを後回しにせず、計画的に進めることが大切です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    7: { title: "実家に関わる法律の基礎知識", body: "実家に関わる法律は近年大きく変わっています。知らないままでいると、思わぬペナルティを受けることがあります。最低限押さえておきたい3つの法律を解説します。\n\n1つ目は「相続登記の義務化」（2024年4月施行）です。不動産を相続した場合、3年以内に登記申請が義務化されました。怠ると10万円以下の過料が科される可能性があります。2つ目は「空家等対策特別措置法」です。管理が不十分な空き家は「特定空き家」に指定され、固定資産税の優遇が外れるほか、行政代執行（強制解体）の対象になることもあります。3つ目は「借地借家法」です。土地を借りている場合の権利関係は複雑で、売却や相続の際に影響します。\n\n法律は専門家でないと判断が難しいため、司法書士や弁護士への相談も検討してみてください。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    8: { title: "実家問題を専門家に相談するには", body: "実家の問題は多岐にわたるため、どの専門家に相談すればいいか迷う方が多いです。相談内容によって適切な専門家が異なります。\n\n「売る・貸す」に関する相談は不動産会社（売却・賃貸）が適しています。「相続・名義」に関しては司法書士（登記）や弁護士（トラブル対応）、税理士（相続税）が専門です。「お金の全体設計」についてはFP（ファイナンシャルプランナー）が幅広く対応してくれます。\n\n最近は複数の専門家がワンストップで対応してくれるサービスも増えています。まずは無料相談を活用して、自分の状況を整理してもらうことをおすすめします。費用は後からかかるとしても、まず相談することで方向性が見えてきます。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    9: { title: "実家に関する補助金・支援制度まとめ", body: "実家の売却・賃貸・リフォーム・解体などには、国や自治体からさまざまな補助金・支援制度があります。知らないと損をすることも多いので、ぜひ確認しておきましょう。\n\n主な制度として、空き家の活用を促進するための「空き家活用補助金」（自治体により異なる）、リフォームに使える「住宅省エネ改修補助金」、解体に使える「老朽危険空き家除却支援事業」、近居・同居を支援する「近居促進補助金」などがあります。\n\nこれらの制度は市区町村によって名称や条件が異なります。自治体の窓口やホームページで確認するか、不動産会社や専門家に「利用できる補助金があるか」を聞いてみましょう。うまく活用すれば、数十万円〜数百万円の支援が受けられることもあります。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] },
    10: { title: "実家問題でよくある後悔と防ぎ方", body: "実家を売却・賃貸・同居した後に「あのときこうしておけばよかった」と後悔する方は少なくありません。よくある後悔パターンを知っておくことで、あなたはそれを避けることができます。\n\n最もよくある後悔は「急いで安く売ってしまった」ことです。複数社に査定を依頼することで数百万円変わることもあります。次に多いのが「同居で家族関係が悪化した」です。ルールを決めずに同居を始め、金銭・家事・プライバシーでもめるケースです。また「相続の話し合いをしなかった」ために兄弟仲が壊れることもあります。\n\n後悔しないためには、焦らず・話し合い・複数の選択肢を比較することが大切です。この記事をきっかけに、まずは診断を受けて現状を整理してみましょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。"}] }
  },
  'baikyaku-col': {
    1: { title: "実家売却の流れと費用【完全ガイド】", body: "実家を売却しようと決めたとき、何から始めればいいのかわからない方がほとんどです。売却には複数のステップがあり、順番を間違えると時間がかかったり損をしたりすることがあります。\n\n売却の流れは大きく「①査定依頼 → ②媒介契約 → ③売却活動 → ④売買契約 → ⑤引き渡し」の5ステップです。まずは複数の不動産会社に査定を依頼することが重要です。1社だけでは相場がわからず、適正価格で売れない可能性があります。\n\nかかる費用としては仲介手数料（売却価格の3%+6万円+消費税）、印紙税、登記費用、譲渡所得税（利益が出た場合）などがあります。特に税金は見落としがちですが、3,000万円特別控除などを活用すれば節税できるケースもあります。専門家に確認しながら進めましょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    2: { title: "不動産一括査定サービスの比較と使い方", body: "一括査定サービスとは、1回の申し込みで複数の不動産会社に査定を依頼できるサービスです。実家の売却を考えたとき、最初に活用すべきツールの一つです。\n\nメリットは「相場感がつかめる」「時間が節約できる」「複数社を比較できる」点です。査定価格は会社によって数百万円違うことがあるため、必ず複数社に依頼することをおすすめします。\n\n注意点は、査定後に各社から営業連絡が来ることです。焦って決めず、担当者の対応・提案内容・会社の実績を比較して選びましょう。査定価格は「この価格で売れると予想される価格」であって「必ず売れる価格」ではないことを念頭に置いてください。一括査定は無料で使えるため、まず試してみる価値があります。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    3: { title: "実家売却で損しないための注意点", body: "実家の売却で失敗する方には共通したパターンがあります。事前に知っておくことで、あなたは同じ失敗を避けられます。\n\n最もよくある失敗は「査定を1社にしか依頼しなかった」ことです。複数社に依頼すれば適正価格がわかります。次に多いのは「瑕疵（かし）の告知漏れ」です。雨漏り・シロアリ・事故など過去のトラブルを隠して売却すると、後で契約不適合責任を問われ多大な損害賠償が発生することがあります。\n\nまた「急いで売ろうとして安値で売却した」ケースも多いです。相続後の手続きに追われ、最初に来た業者に言われるがままに売ってしまうケースです。焦らず複数の選択肢を比較することが大切です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    4: { title: "実家が売れない場合の対処法", body: "不動産を売り出しているのになかなか売れない、という状況はよく起こります。その原因を把握し、適切な対処法を取ることが重要です。\n\n売れない主な原因は3つです。①価格が高すぎる（査定より10%以上高い価格設定）、②立地・築年数などの条件が厳しい（最寄り駅から遠い・旧耐震など）、③売却活動が不十分（物件情報の写真が少ない・ポータルサイト掲載が不足）です。\n\n対処法として、まず価格の見直しを検討しましょう。3ヶ月売れなければ価格調整を検討するのが一般的です。また買取専門業者への依頼も選択肢の一つです。仲介より価格は下がりますが、確実に売却できるため「早く現金化したい」場合に有効です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    5: { title: "築古・訳あり物件の売却方法", body: "旧耐震基準（1981年以前）の物件・事故物件・農地・借地権付き物件など、「訳あり」と呼ばれる物件は通常の売却が難しいことがあります。しかし、適切な方法を選べば売却は可能です。\n\n旧耐震の物件は耐震診断・耐震補強を行うことで売りやすくなりますが、費用がかかります。費用対効果を計算したうえで判断しましょう。事故物件は告知義務があるため必ず開示が必要ですが、告知後でも買主は見つかります。\n\n農地・借地権付き物件は権利関係が複雑なため、専門の不動産会社や司法書士・弁護士に相談することをおすすめします。訳あり物件の買取専門業者は通常の業者より高く評価してくれることもあるため、複数社に相談してみましょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    6: { title: "実家売却の税金と確定申告", body: "実家を売却して利益が出た場合、「譲渡所得税」がかかります。しかし、適切な控除を使えば税負担を大幅に減らすことができます。\n\n譲渡所得の計算式は「売却価格 − 取得費 − 譲渡費用 − 特別控除」です。取得費とは購入時の価格で、不明な場合は売却価格の5%とみなされます。最も大きな節税ポイントは「3,000万円特別控除」です。マイホームを売却する場合、最大3,000万円まで非課税になります。\n\n相続した空き家の場合は一定の要件を満たせば「相続空き家の3,000万円特別控除」が適用されます。適用期限・要件が複雑なため、税理士への相談をおすすめします。税金の知識があるかないかで、手元に残るお金が数百万円変わることもあります。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    7: { title: "リースバックとは？仕組みと注意点", body: "リースバックとは、自宅を不動産会社に売却した後、同じ物件を賃貸として借り直す仕組みです。「売却後も住み続けたい」という方に選ばれています。\n\nメリットは「まとまった資金を得ながら住み続けられる」「引っ越しの手間がない」「固定資産税の支払いがなくなる」点です。老後の生活資金や介護費用の確保として活用する方が増えています。\n\n一方でデメリットもあります。毎月の家賃が発生すること、売却価格が市場価格より低くなること（相場の60〜80%程度）、将来的に再購入できない場合があることです。契約期間・更新条件・買戻し条項をよく確認してから選びましょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    8: { title: "不動産買取と仲介の違い", body: "実家を売却しようとするとき「仲介」と「買取」のどちらを選ぶか、多くの方が悩みます。それぞれの特徴を理解したうえで選択しましょう。\n\n仲介は不動産会社が買主を見つけて売る方法です。市場価格に近い価格で売れる可能性がありますが、買主が見つかるまで3〜6ヶ月以上かかることもあります。買取は不動産会社が直接買い取る方法です。仲介より価格は低くなりますが（相場の60〜80%程度）、数日〜数週間で現金化できます。\n\n仲介が向いているのは「できるだけ高く売りたい」「時間的に余裕がある」場合です。買取が向いているのは「早く現金化したい」「訳あり物件で仲介が難しい」場合です。両方に査定を依頼して比較するのがおすすめです。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    9: { title: "共有名義の実家を売却する方法", body: "兄弟や親族と共有名義になっている実家を売却するには、原則として共有者全員の同意が必要です。意見が合わないとスムーズに進まないことがあります。\n\n全員が同意できる場合は、全員が売買契約に署名・捺印して進めます。一人でも反対する場合は強制的に売ることはできません。この場合の選択肢として「自分の持分だけ売る」（ただし買主が見つかりにくい）、「共有物分割請求訴訟」（裁判所に分割を求める）などがあります。\n\n最もトラブルが多いのは、相続後に「とりあえず全員の名義にした」ままにしているケースです。共有者の誰かが亡くなると、さらに権利関係が複雑になります。共有名義になっている場合は早めに整理することをおすすめします。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    10: { title: "実家売却後の引っ越しと残置物処理", body: "実家の売却が決まったら、引き渡しまでに荷物の整理と清掃が必要です。買主に良い印象を与えるためにも、丁寧に対応しましょう。\n\n残置物（荷物）は原則として売主側で処分します。不用品はリサイクルショップへの売却、自治体の粗大ごみ回収、遺品整理業者への依頼などで処理しましょう。引き渡し前にハウスクリーニングを行うことで印象が良くなり、売却価格の維持につながります。\n\n引き渡し時には「付帯設備表」「物件状況確認書」を正確に記載することが重要です。故障している設備・過去の修繕履歴などを正直に記載することで、引き渡し後のトラブルを防げます。不明点は不動産会社に確認しながら進めましょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    11: {
      title: '築古・空き家でも売れる？訳あり物件買取サービス「ワケガイ」を活用する前に知っておきたいこと',
      body: `「こんな古い家、誰も買わないよね」と感じていませんか。

親が亡くなって実家が空き家になり、売却しようと思っても「築年数が古すぎる」「雨漏りがある」「田舎で需要がない」といった理由で、普通の不動産会社には断られてしまった——そんな経験をされた方は少なくありません。

管理のために帰省するたびに時間とお金がかかり、固定資産税だけが毎年引き落とされていく。そのうち「もう手放したい」と思いながらも、どこに相談すればいいかわからず、時間だけが過ぎてしまっているのではないでしょうか。

**こんな悩みを抱えていませんか？**
・築古・訳あり物件は仲介会社に断られてしまった
・空き家のまま固定資産税・管理費を払い続けている
・遠方で管理に行くたびに交通費・時間がかかっている
・雨漏りや老朽化が進んでいて、このまま放置していいか不安

**使わない場合に起こりやすい状況**
空き家を放置していると、建物の老朽化は年々進みます。自治体から「特定空き家」に指定されると固定資産税の優遇措置が外れ、税負担が増える可能性があります。すぐに大きな問題にはならないケースも多いですが、時間が経つほど選択肢が狭まりやすい傾向があります。

**このサービスが役立つ可能性がある理由**
ワケガイが役立つ可能性があるのは、「仲介では売れない」と言われた物件を持つ方です。

通常の不動産売却（仲介）は、買主となる一般の方が見つかって初めて成立します。そのため、築古・訳あり・田舎の物件は買主が見つかりにくく、仲介会社に取り扱いを断られるケースも少なくありません。

ワケガイのような買取専門サービスは、業者が直接物件を購入するため、一般の買主を探す必要がありません。その結果、仲介では売れないとされた物件でも買取の対象になる場合があります。

現状渡しOKという点も、遠方に住んでいて管理が難しい方にとっては手間を減らしやすくなります。最短2週間での現金化が可能とされており、「早く手放して管理の負担から解放されたい」という方の状況に合いやすいサービスといえます。

**利用すると期待できる変化**
・仲介で断られていた物件でも、査定を受けやすくなる可能性があります
・片付けやリフォームなしで手続きを進めやすくなる場合があります
・固定資産税や管理費の負担から解放されやすくなります

**向いている人**
・築古・訳あり・空き家物件を早期に手放したい方
・仲介会社に断られた経験がある方
・遠方で物件の管理が難しい方

**向いていない人**
・できるだけ高い価格で売却することを最優先にしている方
・時間をかけてじっくり条件のいい買主を探したい方

**利用前に確認したいこと**
・買取価格は仲介売却と比べて低くなる場合があります。仲介との比較検討をおすすめします
・対応可能エリアや物件の種類によって、買取できないケースもあります
・査定は無料で、査定後に売却するかどうかは自分で判断できます

**よくある質問**
Q. 荷物がたくさん残っていても買取ってもらえますか？
A. 現状渡しに対応している場合が多いです。まず査定時に確認してみてください。

Q. 築50年以上の建物でも査定してもらえますか？
A. 訳あり・築古物件を専門としているため、査定を受けられる場合があります。まずは無料査定で状況を確認するのが一つの方法です。

「こんな物件は売れない」と諦めてしまう前に、買取専門サービスに査定を依頼してみることが、状況を整理する一つのきっかけになるかもしれません。`,
      a8: [          { name: 'ワケガイ（訳あり物件買取）', url: 'https://px.a8.net/svt/ejp?a8mat=4B3VR7+BH6VDM+5J56+5Z6WX', desc: '訳あり・築古・空き家も買取。最短2週間で現金化。', serviceSlug: 'wakegai', imgUrl: 'https://www28.a8.net/svt/bgt?aid=260521603694&wid=002&eno=01&mid=s00000025809001004000&mc=1', imgWidth: 100, imgHeight: 60, impUrl: 'https://www10.a8.net/0.gif?a8mat=4B3VR7+BH6VDM+5J56+5Z6WX' }],
    },

    12: {
      title: '空き家を放置していませんか？現状渡しOKの買取サービスで手放すまでの流れを解説',
      body: `「あの家、どうしようか」と思いながら、もう何年も経っていませんか。

親が施設に入ったり亡くなったりして、実家が空き家になった。でも古い家だし、片付けるだけでも大変だし、遠くて管理も難しい。売れるかどうかもわからないから、とりあえずそのままにしている——。

**こんな悩みを抱えていませんか？**
・空き家の管理のために遠方から帰省する負担が続いている
・古い家で売れるかどうかわからず、動き出せていない
・片付けやリフォームをする時間・体力・費用がない
・固定資産税・管理費を払い続けることへの負担感がある

**このサービスが役立つ可能性がある理由**
ラクウルの空き家・中古戸建買取サービスが役立ちやすいのは、「片付けや修繕をする余裕がない」「とにかく早く手放したい」という方です。

現状渡しに対応しているため、荷物が残っていても、古いままの状態でも査定を受けやすいというのが特徴の一つです。最短3日で査定結果が出るとされており、「まず現状を把握したい」という方にとっても情報収集の入口として活用しやすいサービスです。

**利用すると期待できる変化**
・現状のまま査定を依頼しやすくなります
・片付けやリフォームの手間なく手続きを進められる可能性があります
・「売れるかどうかわからない」という状況を、査定結果をもとに整理しやすくなります

**向いている人**
・空き家の管理に長期間困っている方
・片付けや修繕をする余裕がない方
・まず査定だけでも受けてみたい方

**向いていない人**
・できるだけ高値での売却を最優先にしている方

**よくある質問**
Q. 荷物がそのまま残っていても大丈夫ですか？
A. 現状渡しに対応しているため、荷物が残っていても査定を受けられる場合があります。

Q. 査定だけして、売らなくてもいいですか？
A. 無料査定を受けた後、売却するかどうかは自分で判断できます。

空き家をどうするか決めかねている間も、時間は経過します。「まず査定だけでも」という気持ちで動いてみることが、状況を整理する第一歩になるかもしれません。`,
      a8: [          { name: 'ラクウル（空き家・中古戸建買取）', url: 'https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HW2Q9', desc: '空き家・中古戸建て買取専門。現状のままで査定OK。', serviceSlug: 'rakuuru-akiya', imgUrl: 'https://www22.a8.net/svt/bgt?aid=260521603741&wid=002&eno=01&mid=s00000024144003005000&mc=1', imgWidth: 300, imgHeight: 120, impUrl: 'https://www15.a8.net/0.gif?a8mat=4B3VR7+C968T6+56AO+HW2Q9' }],
    },
  },
  'akiya-col': {
    1: { title: "空き家を放置するとどうなる？リスクと対策", body: "実家が空き家になって数年が経つ、という方は意外と多いです。「いつか考えよう」と放置している間に、様々なリスクが積み重なっていきます。\n\n空き家を放置することで起こる主なリスクは4つです。①固定資産税の増加（特定空き家に指定されると最大6倍）、②建物の劣化（無人のため換気・点検がされず、雨漏り・シロアリが進む）、③近隣トラブル（雑草・害虫・不法投棄など）、④犯罪リスク（放火・不法侵入など）です。\n\n対策としては「定期的な管理・見回り」または「売却・賃貸などで活用」が基本です。自分で管理が難しい場合は空き家管理サービスを活用する選択肢もあります。月1〜2万円程度で定期点検・清掃を行ってくれる業者があります。放置しているリスクを理解したうえで、早めに方針を決めることが重要です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    2: { title: "特定空き家に指定されないための対策", body: "「特定空き家」に指定されると、固定資産税の優遇措置が外れ、最終的には行政が強制解体することもあります。どういう状態になると指定されるのかを理解しておきましょう。\n\n特定空き家の指定基準は「そのまま放置すれば倒壊等著しく保安上危険」「著しく衛生上有害」「著しく景観を損なっている」「周辺の生活環境の保全を図るために放置することが不適切」の4つです。傾いている・屋根が崩れかけている・悪臭がする・近隣から苦情が来ている、などの状態が対象になります。\n\n指定されると、まず市区町村から「助言・指導」が来ます。それでも改善されなければ「勧告」→「命令」→「行政代執行（強制解体）」という流れで進みます。行政代執行の費用は所有者に請求されます。このような事態を避けるためにも、空き家の早期対処が重要です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    3: { title: "空き家の管理方法と管理サービス", body: "空き家を遠隔地から管理するのは大変です。「なかなか帰省できない」「毎回交通費と時間がかかる」という方には、空き家管理サービスの活用をおすすめします。\n\n空き家管理サービスでは、定期的な見回り（月1〜2回）・換気・通水（錆び防止）・郵便物の管理・清掃・点検報告などを行ってくれます。費用は月5,000〜2万円程度が目安で、立地や管理内容によって異なります。\n\n自分で管理する場合は、定期的な帰省に加えて電気・ガス・水道の維持、庭の手入れ、雨漏りのチェックなどが必要です。特に冬季は水道管の凍結防止が重要です。売却や賃貸を検討するなら、早めに動いたほうが建物の状態が良く高く評価されます。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    4: { title: "空き家バンクへの登録方法", body: "空き家バンクとは、市区町村が運営する空き家のマッチングサービスです。売りたい・貸したいオーナーと、購入・入居希望者をつなぐ仕組みです。\n\n登録の流れは「①自治体窓口に相談 → ②物件情報の登録 → ③見学・交渉 → ④成約」です。登録・掲載は無料の自治体が多く、移住促進を目的としているため田舎・地方の物件が多い傾向があります。\n\n空き家バンクのメリットは費用が安いことですが、デメリットとして成約までに時間がかかる点・自分で交渉・手続きを行う必要がある点があります。都市部の物件には向きにくいですが、田舎の実家を処分したい場合には有効な選択肢です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    5: { title: "空き家のリフォーム・リノベーション費用", body: "空き家を賃貸・売却できる状態にするためにリフォームが必要な場合があります。どれくらいの費用がかかるのか、補助金は使えるのかを事前に把握しておきましょう。\n\nリフォームの費用相場は内容によって大きく異なります。内装（クロス・床）の張り替えで50〜100万円、水回り（キッチン・浴室・トイレ）の交換で100〜200万円、外壁塗装で80〜150万円、耐震補強で100〜200万円が目安です。\n\n補助金としては「長期優良住宅化リフォーム推進事業」「省エネリフォーム補助金」「耐震改修補助金」など国や自治体が提供するものがあります。リフォーム費用と売却・賃貸収入のバランスを計算したうえで、どこまでリフォームするか判断することが重要です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    6: { title: "空き家の解体費用と補助金", body: "空き家を解体して更地にすることで、売却しやすくなる場合があります。ただし解体費用は決して安くはないため、慎重に判断する必要があります。\n\n解体費用の相場は建物の構造・大きさによって異なります。木造住宅（30〜40坪）で100〜200万円、鉄骨造で150〜250万円、RC造（コンクリート）で200〜350万円程度が目安です。\n\nただし解体後は固定資産税の優遇（住宅用地の6分の1軽減）が外れるため、税額が増加します。一方で、自治体によっては「老朽危険空き家除却補助金」として解体費用の一部（20〜50%程度）を補助してくれる場合があります。解体前に自治体の補助金制度を必ず確認しましょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    7: { title: "空き家を民泊・シェアハウスにする方法", body: "活用方法に悩んでいる空き家を民泊やシェアハウスとして運営することで、収益を得られる可能性があります。ただし法律上の手続きが必要です。\n\n民泊として運営するには「住宅宿泊事業法（民泊新法）」に基づく届出が必要です。年間営業日数は180日以内という制限があり、地域によってはさらに厳しい規制があります。運営代行業者に委託することで、清掃・予約対応を任せることができます。\n\nシェアハウスは複数人に部屋を貸す賃貸形式で、空き家を有効活用できます。初期投資（リフォーム・設備）が必要ですが、複数人から家賃を得られるため収益性が高い場合があります。地域の需要を事前に調査したうえで収益シミュレーションを行うことが重要です。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    8: { title: "相続した空き家の売却と税金", body: "相続した空き家を売却した場合、一定の条件を満たすと「3,000万円特別控除」が適用されます。通常の売却との違いを理解しておきましょう。\n\n「相続空き家の3,000万円特別控除」は、相続した空き家を売却する際に譲渡所得から3,000万円を差し引ける特例です。適用条件は①1981年5月31日以前に建築された家屋②相続から売却まで空き家であった③売却額が1億円以下④耐震基準を満たす（または解体して更地で売る）などです。\n\nこの特例は2027年12月31日まで延長されています。適用できるかどうかは個別の状況によって異なるため、売却前に必ず税理士に確認することをおすすめします。うまく活用すれば税負担が大幅に軽減される可能性があります。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    9: { title: "田舎の空き家をどうするか", body: "都市部から離れた田舎の実家は、需要が低く売却・賃貸が難しいことがあります。しかし、近年は移住ブームや地方活性化の流れを受けて、田舎の空き家への関心が高まっています。\n\n田舎の空き家に特有の課題として「農地が隣接していて売却に農地法の手続きが必要」「インフラ（水道・ガス・道路）の整備が不十分」「買い手・借り手の絶対数が少ない」などがあります。\n\n一方で可能性もあります。移住者向けの「空き家バンク」への登録、民泊・農家民宿としての活用、地方移住を検討する若い世代へのアプローチなどです。自治体が移住促進補助金を出しているケースも多く、田舎の空き家は「価値がない」と思わず、地域の移住相談窓口にも問い合わせてみましょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    10: { title: "空き家になる前にできる予防策", body: "もし実家が空き家になることがわかっているなら、なる前に対策を取ることが最善です。事後対応より事前対応のほうが、コストも手間も少なく済みます。\n\n親が元気なうちにやっておくべきことは「荷物の整理（生前整理）」「権利関係の確認（登記・借地権）」「修繕が必要な箇所のチェック」「売却・賃貸の意向確認」などです。特に荷物の整理は親と一緒に行うことで、思い出の品を適切に処理でき、後から遺品整理業者に高額を支払う必要がなくなります。\n\nまた「親が認知症になる前に」手続きを済ませることも重要です。認知症になると財産の処分が法的に制限され、売却ができなくなることがあります。家族信託や成年後見制度についても早めに検討しておくとよいでしょう。", a8: [{name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    11: {
      title: '親の遺品整理、自分たちだけでは無理？プロに頼む前に知っておきたいこと',
      body: `「物が多すぎて、自分たちだけでは無理だ」と感じていませんか。

親が亡くなった後、実家には長年の暮らしが詰まっています。家具・衣類・書類・思い出の品——。整理しようと思っても、量が多すぎるし、悲しみの中で作業するのは心身ともに辛い。遠方からわざわざ帰省して、何日もかけても終わらない、ということも珍しくありません。

**こんな悩みを抱えていませんか？**
・遺品の量が多すぎて自分たちでは片付けられない
・悲しみの中で作業するのが心身ともに辛い
・遠方からの帰省を繰り返すのが体力的・経済的に負担
・業者に頼む費用の相場がわからない

**このサービスが役立つ可能性がある理由**
プロの遺品整理業者に依頼することで、大量の荷物をまとめて整理・処分してもらえる可能性があります。自分たちで何日もかけて作業するのと比べて、短期間で片付けが完了しやすくなります。

買取に対応している業者の場合、価値のあるものを買い取ってもらえることで費用の一部が相殺される可能性もあります。遺品整理が完了することで、その後の実家の売却・活用・解体などの手続きに進みやすくなります。

**向いている人**
・遺品の量が多く自分たちでは片付けられない方
・遠方で何度も帰省しての作業が難しい方

**向いていない人**
・自分たちのペースでゆっくり整理したい方

**よくある質問**
Q. 費用はどのくらいかかりますか？
A. 荷物の量・部屋の広さ・地域によって大きく異なります。まず見積もりを依頼して確認するのがおすすめです。

Q. 買取もしてもらえますか？
A. 買取に対応している業者の場合、価値のある品物を買い取ってもらえる可能性があります。詳細は見積もり時に確認してください。`,
      a8: [          { name: 'ライフリセット（遺品整理）', url: 'https://px.a8.net/svt/ejp?a8mat=4B5LK3+1GZLMA+36X8+1ZHAW1', desc: '遺品整理・不用品回収のプロ。相続後の片付けをサポート。', serviceSlug: 'liferesa', imgUrl: 'https://www23.a8.net/svt/bgt?aid=260601699089&wid=001&eno=01&mid=s00000014894012006000&mc=1', imgWidth: 300, imgHeight: 250, impUrl: 'https://www10.a8.net/0.gif?a8mat=4B5LK3+1GZLMA+36X8+1ZHAW1' }],
    },
  },
  'sozoku-col': {
    1: { title: "実家の相続でもめないための5つの準備", body: "実家を含む相続は、家族の感情・金銭・法律が絡み合う複雑な問題です。相続がもめる「争族」にならないためには、事前の準備が欠かせません。\n\n相続トラブルを防ぐための5つの準備を紹介します。①遺言書の作成（誰に何を残すか明確にする）②家族会議の実施（生前に意向を共有する）③財産目録の作成（不動産・預貯金・保険を一覧化する）④専門家への相談（税理士・司法書士・弁護士）⑤記録化（話し合いの内容を書き留めておく）です。\n\n特に遺言書は「自筆証書遺言」「公正証書遺言」の2種類があります。法的に有効な形式で作成することが重要です。「うちは仲良いから大丈夫」という家ほど相続後に揉めるケースが多いため、早めの準備をおすすめします。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    2: { title: "相続登記の義務化と手続き方法", body: "2024年4月から、不動産の相続登記が義務化されました。これにより、相続した不動産の名義変更を怠ると罰則を受けることがあります。\n\n以前は義務ではなかったため、何十年も名義変更がされていない「所有者不明土地」が社会問題化していました。義務化により、相続を知った日から3年以内に登記申請が必要になりました。怠ると10万円以下の過料が科される可能性があります。\n\n手続きは法務局で行います。必要書類は被相続人の戸籍謄本（出生〜死亡）・相続人全員の戸籍謄本・遺産分割協議書（相続人全員の署名・実印）・固定資産評価証明書などです。複雑なため司法書士に依頼するのが一般的で、費用は5〜15万円程度が目安です。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    3: { title: "実家を誰が相続するか決める方法", body: "実家を含む遺産をどう分けるかは、相続人全員が合意する必要があります。法律で決まっている「法定相続分」を理解したうえで、家族の実情に合わせた分け方を選びましょう。\n\n法定相続分は「配偶者+子供」の場合、配偶者1/2・子供全員で1/2を均等分けが基本です。不動産は物理的に分けられないため、主な方法は3つです。①現物分割（誰か一人が取得し他の相続人に代償金を払う）②換価分割（売却して現金を分ける）③共有（全員の共有名義にする）です。\n\n最も問題が少ないのは「換価分割」（売却して現金分配）ですが、実家への思い入れがある場合は難しいことがあります。いずれの方法も全員が合意することが前提で、合意できない場合は家庭裁判所の調停・審判に移行します。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    4: { title: "実家の相続税の計算方法", body: "実家を含む相続では「相続税がかかるのかどうか」を確認することが重要です。実は相続税がかかるのは全体の約1割程度の方で、多くの場合は基礎控除内に収まります。\n\n相続税の基礎控除額は「3,000万円 + 600万円 × 法定相続人の数」です。例えば配偶者と子供2人の場合は3,000万円 + 600万円×3人 = 4,800万円が控除されます。財産の総額がこれを超える場合に相続税が発生します。\n\nまた「小規模宅地等の特例」を使うと、自宅の土地の評価額を最大80%減額できる場合があります。相続税の計算は複雑なため、必ず税理士に相談することをおすすめします。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    5: { title: "遺産分割協議書の書き方", body: "遺産分割協議書とは、相続人全員が遺産の分け方に合意した内容を記した書面です。不動産の相続登記や預貯金の解約手続きに必要になります。\n\n記載すべき内容は「被相続人の情報（氏名・生年月日・死亡日・住所）」「不動産の情報（登記簿記載の所在・地番・面積など）」「誰が何を相続するか」「作成日」「相続人全員の署名・実印・印鑑証明書」です。\n\n注意点として、記載ミスや漏れがあると登記できないことがあります。また一度作成・署名した協議書は原則として撤回できません。全員が内容を十分に確認してから署名しましょう。司法書士や弁護士に依頼すると確実で、費用は5〜10万円程度が目安です。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    6: { title: "相続放棄の手続きと期限", body: "相続放棄とは、プラスの財産もマイナスの財産（借金）もすべて相続しないことを選択する手続きです。実家に多額のローンが残っている場合などに有効です。\n\n相続放棄は「相続の開始があったことを知った日から3ヶ月以内」に家庭裁判所に申請する必要があります。必要書類は申述書・被相続人の戸籍謄本・申述人の戸籍謄本などです。\n\n注意点として、相続放棄すると不動産の処分もできなくなります。また放棄した財産は次の順位の相続人（兄弟姉妹・おじ・おばなど）に移ることです。親族に思わぬ相続が発生するため、事前に関係者に伝えておきましょう。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    7: { title: "生前贈与で実家を子供に渡す方法", body: "生前贈与とは、亡くなる前に財産を子供や孫に贈与することです。相続税対策として活用されますが、贈与税との兼ね合いも考慮する必要があります。\n\n主な制度として3つあります。①暦年贈与（年110万円まで非課税）②相続時精算課税制度（2,500万円まで非課税だが相続時に合算される）③住宅取得等資金贈与（子・孫への住宅購入資金は最大1,000万円まで非課税）です。\n\n注意点として、2024年以降の税制改正により暦年贈与の持ち戻し期間が3年から7年に延長されました。実家を生前贈与する場合は登録免許税・不動産取得税がかかるため、相続時の費用と比較して判断することが重要です。必ず税理士・FPに相談してから実行しましょう。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    8: { title: "家族信託で実家を管理する方法", body: "家族信託とは、財産の管理・処分を信頼できる家族に委託する仕組みです。特に親が認知症になった場合の財産管理対策として注目されています。\n\n家族信託の仕組みは「委託者（親）が受託者（子供）に財産の管理を任せる」というものです。認知症になると通常は財産の処分ができなくなりますが、事前に信託契約を結んでおけば子供が代わりに管理・売却できます。\n\n費用は設定時に30〜100万円程度かかることが多く、弁護士・司法書士への依頼が必要です。成年後見制度と異なり、家族信託は家族主導で柔軟に運用できる点が特徴です。実家の将来について親が元気なうちに話し合い、必要であれば早めに手続きを取ることをおすすめします。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    9: { title: "実家の相続でよくあるトラブルと解決法", body: "実家の相続でよくあるトラブルパターンを知っておくことで、あなたはそれを事前に回避できます。\n\n最もよくあるトラブルは「不動産の評価をめぐる対立」です。誰かが実家を相続したいが、その場合に他の相続人へ支払う代償金の計算で意見が割れるケースです。次に多いのが「寄与分・特別受益の主張」です。「自分だけ親の介護をした」「あの人だけ生前に多くの援助を受けた」という主張がトラブルになります。\n\nこれらを防ぐには、生前から親の意向を明確にし遺言書に残しておくことが最善です。トラブルが発生した場合は家庭裁判所の調停を利用しましょう。弁護士に依頼することで話し合いをスムーズに進めることができます。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    10: { title: "税理士・司法書士・弁護士の選び方", body: "相続においては税理士・司法書士・弁護士・FPなど複数の専門家が関わります。それぞれの役割を理解して、適切な専門家に相談しましょう。\n\n税理士は「相続税の申告・節税対策」が専門です。司法書士は「相続登記（不動産の名義変更）」が専門で、法務局への申請を代行してくれます。弁護士は「相続トラブルの解決・調停・訴訟」が専門です。FPは「相続を含むお金全体の相談」ができます。\n\n最近は複数の専門家がワンストップで対応するサービスも増えており、窓口が一つになることで手続きが楽になります。費用は「相続財産の1%前後（税理士）」「5〜15万円（司法書士）」「時間制または成功報酬（弁護士）」が目安です。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続の面倒ごとをワンストップで解決。税理士・司法書士・弁護士が連携。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売っても住み続けられるリースバック。"}] },
    11: {
      title: '相続手続きは何から始める？専門家チームに丸ごと任せる「相続アシスト」とは',
      body: `「相続手続きって、何から始めればいいの？」

親が亡くなって間もない頃、さまざまな手続きが次々と押し寄せてきます。銀行口座の凍結、相続登記の義務化、相続税の申告期限——。調べれば調べるほど、専門用語が出てきて、誰に何を頼めばいいのかわからなくなってしまう方も少なくありません。

**こんな悩みを抱えていませんか？**
・相続手続きの全体像がわからず、何から手をつければいいかわからない
・税理士・司法書士・弁護士のどこに頼めばいいかわからない
・相続登記の義務化で期限内に動かなければいけないが、方法がわからない
・相続税がかかるのか、かからないのかもわからない

**使わない場合に起こりやすい状況**
相続手続きを放置していた場合、相続登記については義務化されており、期限を過ぎると過料が発生する可能性があります。また相続税の申告期限（被相続人の死亡を知った日の翌日から10か月以内）を過ぎると、加算税・延滞税が発生する可能性があります。

**このサービスが役立つ可能性がある理由**
相続アシストが役立つ可能性があるのは、「相続手続きを専門家に丸ごと任せたい」という方です。

相続手続きは、税理士・司法書士・弁護士それぞれの専門領域にまたがります。それぞれに個別に依頼すると、情報の連携が取れなかったり、自分でコーディネートしなければならなかったりと、手間がかかります。

相続アシストは、これらの専門家がチームで対応するワンストップサービスです。窓口を一本化できるため、「誰に何を頼めばいいかわからない」という状況を整理しやすくなる可能性があります。

**向いている人**
・相続手続きを専門家にまとめて任せたい方
・相続税の申告が必要な可能性がある方
・不動産の相続登記が必要な方

**向いていない人**
・相続財産が基礎控除内で、相続税の申告が不要な方

**よくある質問**
Q. 相続税がかかるかどうかわからないのですが相談できますか？
A. はい、相談可能です。相続財産の総額を確認した上で、申告が必要かどうかを判断することができます。

Q. 費用はどのくらいかかりますか？
A. 相続財産の規模・内容によって異なります。まずは見積もりを依頼して確認することをおすすめします。

相続手続きは、時間的な期限があるものが多く、早めに動き出すことが大切です。まずワンストップで対応できる専門家チームに相談してみることが、全体像を把握する第一歩になるかもしれません。`,
      a8: [          { name: '相続アシスト', url: 'https://af.moshimo.com/af/c/click?a_id=5647169&p_id=7301&pc_id=20977&pl_id=93281', desc: '相続の手間も不安も、まるごとゼロに。ゼロタッチ相続税申告。', serviceSlug: 'sozoku-assist', imgUrl: 'https://image.moshimo.com/af-img/3982/000000093281.png', imgWidth: 300, imgHeight: 250, impUrl: 'https://i.moshimo.com/af/i/impression?a_id=5647169&p_id=7301&pc_id=20977&pl_id=93281' }],
    },
  },
  'chintai-col': {
    1: { title: "実家を賃貸に出すメリット・デメリット", body: "実家を賃貸に出すことで毎月の収入を得られます。しかし、賃貸経営にはメリットだけでなくデメリットもあります。十分に理解したうえで判断しましょう。\n\nメリットは「毎月の家賃収入が得られる」「実家を手放さずに済む」「将来的に戻ることができる」点です。一方でデメリットも少なくありません。「空室リスク（借り手がいない期間は収入ゼロ）」「修繕費・管理費がかかる」「入居者トラブルの可能性」「確定申告が必要になる」などです。\n\n賃貸を成功させるためには立地・築年数・設備が重要な要素になります。まずは不動産会社に「賃貸に出した場合の想定家賃」を査定してもらいましょう。賃料収入と維持コストのバランスを計算し、売却と比較したうえで判断することをおすすめします。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    2: { title: "賃貸管理会社の選び方と手数料", body: "実家を賃貸に出す場合、管理会社に依頼するかどうかを決める必要があります。自主管理と管理委託の違いを理解して選びましょう。\n\n賃貸管理会社に依頼する場合、「入居者の募集・審査」「家賃の集金・滞納対応」「入退去の手続き」「修繕対応」などを代行してもらえます。費用は家賃の5〜10%程度（月額）が相場です。\n\n自主管理のメリットは費用が節約できる点ですが、入居者対応・トラブル処理・空室対策などをすべて自分で行う必要があります。管理会社を選ぶポイントは「管理戸数・実績」「対応スピード」「費用体系の透明性」「担当者の誠実さ」です。複数社を比較して選びましょう。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    3: { title: "サブリース契約の仕組みと注意点", body: "サブリースとは、不動産会社が物件を一括で借り上げ、入居者に又貸しする仕組みです。「空室でも家賃が入る」という安心感から選ぶオーナーが多いですが、注意点もあります。\n\nメリットは「空室リスクがない（入居者がいなくても家賃保証）」「管理の手間がかからない」点です。しかしデメリットも重要です。「保証賃料は相場の80〜90%程度になる」「定期的な賃料の見直し（減額）がある」「解約が難しく違約金が発生することがある」などです。\n\nサブリース契約を検討する際は、契約書の内容を細かく確認することが重要です。特に「賃料改定条項」「解約条件」「免責事項」は要チェックです。甘い言葉での営業勧誘も多いため、国土交通省の「サブリース業者に関するトラブルに注意」も参考にしてください。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    4: { title: "実家をリフォームして賃貸に出す費用", body: "実家をそのまま賃貸に出すことが難しい場合、リフォームすることで入居者を見つけやすくなります。どこをどれだけリフォームすべきかを判断しましょう。\n\n賃貸リフォームで優先度が高いのは「水回り（キッチン・トイレ・バス）」と「内装（クロス・床）」の更新です。これらは入居者が最も気にする部分で、古い場合は大きなマイナス要因になります。費用は水回り交換で100〜200万円、内装で50〜100万円が目安です。\n\n一方で「全面的なフルリフォームは必ずしも必要ない」ことも覚えておきましょう。リフォーム費用を回収するには何年かかるかを計算したうえで判断することが重要です。不動産会社に「このくらいリフォームすれば〇万円の家賃で貸せる」という見解を聞きながら判断するのがベストです。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    5: { title: "実家の賃貸収入の確定申告方法", body: "実家を賃貸に出して家賃収入を得た場合、確定申告が必要になります。サラリーマンの方でも例外ではありません。\n\n不動産所得は「家賃収入 − 必要経費」で計算されます。経費として認められるものは「管理費・修繕費・減価償却費・火災保険料・固定資産税・借入金利息・交通費（管理のための）」などです。必要経費をしっかり計上することで節税できます。\n\n確定申告は毎年2月16日〜3月15日に行います。青色申告を選択すると、最大65万円の特別控除が受けられます（複式簿記での記帳が条件）。継続的に賃貸経営をする場合は青色申告を選ぶことをおすすめします。税務署の無料相談や税理士への依頼も活用しましょう。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    6: { title: "実家を民泊で活用する方法", body: "実家が観光地の近くや都市部にある場合、民泊として活用する選択肢があります。ただし法律上の手続きが必要です。\n\n民泊には「住宅宿泊事業法（民泊新法）」に基づく届出が必要です。年間営業日数は180日以内（一部地域ではさらに制限あり）で、消防法や衛生管理基準への適合も求められます。届出後はAirbnbなどの民泊プラットフォームを通じて集客が可能です。\n\n収益は立地・設備・稼働率によって大きく変わります。観光地近くであれば月10〜30万円の収入が期待できることもありますが、清掃・対応・設備維持に手間がかかります。自分で管理できない場合は民泊代行業者に委託する選択肢もあります。地域の需要と法規制を確認したうえで判断しましょう。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    7: { title: "農地付きの実家の活用方法", body: "実家に農地が隣接・付属している場合、活用方法が限られることがあります。農地には独自のルールがあるため、事前に確認が必要です。\n\n農地を売却・転用するには農業委員会の許可が必要です（農地法3条・4条・5条）。市街化区域内の農地は届出だけで転用できますが、市街化調整区域の農地は転用が原則禁止です。農地のまま売る場合は農家または農業参入企業への売却が基本です。\n\n活用方法として「貸し農園（市民農園）」「農家民宿」「農業体験観光」なども検討できます。特に都市近郊の農地は市民農園として月3,000〜5,000円/区画で貸し出すと安定収入が得られます。農地の扱いは複雑なため、農業委員会や専門家に相談することをおすすめします。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    8: { title: "実家を事務所・店舗として使う方法", body: "実家を自分のビジネスの事務所や店舗として活用することで、費用を節約しながら実家を維持できることがあります。\n\n自宅兼事務所として使う場合、按分（使用割合に応じた経費計上）が可能です。例えば仕事で使用する部屋が全体の30%であれば、固定資産税・ローン利息・光熱費の30%を経費にできます。ただし「実態のある業務使用」であることが条件です。\n\n店舗として使う場合は「用途変更」の手続きが必要なことがあります（建築基準法）。また「第一種低層住居専用地域」などでは店舗が建てられないエリアもあるため、物件の用途地域を確認することが重要です。実家の活用として自分のビジネスと組み合わせることで、賃貸・売却以外の可能性が広がります。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    9: { title: "空き家を活用した地域貢献の方法", body: "空き家を地域コミュニティの場として提供することで、社会貢献しながら実家を維持・活用することができます。近年、こうした取り組みが全国で広がっています。\n\n活用事例として「子ども食堂」「コミュニティカフェ（地域住民の交流の場）」「移住者向けの体験滞在施設」「地域の作業場・工房」などがあります。NPOや自治体と連携することで、改修費用の補助や運営サポートが受けられる場合もあります。\n\nこうした活用方法は収益面では大きくないことが多いですが「実家を誰かに使ってもらえる満足感」「維持管理の負担軽減」「地域との繋がり」といった価値があります。すぐに売却・賃貸できない実家でも、地域貢献という形で活用できる可能性があります。自治体や地域のNPOに相談してみましょう。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] },
    10: { title: "実家の賃貸と売却、どちらが得かシミュレーション", body: "実家を「賃貸に出す」か「売却する」か迷っている方のために、10年間の収支をシミュレーションして比較してみましょう。\n\n【売却の場合】例えば2,000万円で売却できた場合、その資金を年利1%で運用すると10年で210万円の利益（概算）。維持コストゼロで2,210万円の手元資金になります。【賃貸の場合】月8万円の家賃で貸した場合、年96万円×10年＝960万円の収入。しかし管理費・固定資産税・修繕費を差し引くと、実質手取りは700〜800万円程度になります。\n\nどちらが有利かは物件の立地・状態・市場動向によって変わります。不動産会社に具体的なシミュレーションを依頼してみることをおすすめします。", a8: [{name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "自宅を売却後もそのまま住めるリースバック。"}, {name: "ラクウル（空き家・中古戸建買取）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C968T6+56AO+HV7V6", desc: "空き家・中古戸建ての買取専門。最短3日で査定。"}] }
  },
  'dokyo-col': {
    1: { title: "親との同居を成功させる7つのルール", body: "親との同居は「介護・生活費の節約・子育て支援」などメリットがある一方、うまくいかないと家族関係が壊れることもあります。成功させるための7つのルールを紹介します。\n\nルール①費用分担を明確にする②家事分担を話し合う③プライベートの時間を確保する④子どもの教育方針を統一する⑤来客・友人への対応を決める⑥金銭的な援助の範囲を決める⑦定期的にルールを見直す（半年〜1年ごとに話し合いの場を設ける）です。\n\nルールを「最初に決めること」が最も重要です。後から言い出すと「今更なぜ」という感情的対立になりがちです。同居前の話し合いが成功の鍵を握っています。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    11: {
      title: '実家のリフォーム業者はどう選ぶ？一括見積もりサービスで比較する前に知っておきたいこと',
      body: `「リフォームって、どこに頼めばいいの？」\n\n実家を二世帯住宅にしたい、老朽化した水回りを直したい、同居に向けて間取りを変えたい——。そう思っていても、リフォーム業者をどうやって探して、どう選べばいいかわからないという方は多いです。\n\n**こんな悩みを抱えていませんか？**\n・リフォーム費用の相場がわからない\n・業者を1社しか知らないので比較できない\n・悪質な業者を選んでしまわないか不安\n\n**このサービスが役立つ可能性がある理由**\nRe:estが役立つ可能性があるのは、複数のリフォーム業者に見積もりを依頼して比較したい方です。一括見積もりサービスを使うことで、複数社に同じ条件で見積もりを依頼でき、費用・工事内容を比較しやすくなります。\n\n**向いている人**\n・リフォームを検討しているが費用相場がわからない方\n・複数社を比較してから業者を選びたい方\n\n**向いていない人**\n・すでに依頼する業者が決まっている方`,
      a8: [{ name: 'Re:est（リフォーム見積もり）', url: 'https://px.a8.net/svt/ejp?a8mat=4B3VR7+BLCWM2+5UT6+5ZMCH', desc: '後悔しない業者選びなら！リフォーム一括見積もりサービス。', serviceSlug: 'reest', imgUrl: 'https://www29.a8.net/svt/bgt?aid=260521603701&wid=002&eno=01&mid=s00000027321001006000&mc=1', imgWidth: 300, imgHeight: 250, impUrl: 'https://www13.a8.net/0.gif?a8mat=4B3VR7+BLCWM2+5UT6+5ZMCH' }],
    },
    2: { title: "二世帯住宅のメリット・デメリット", body: "二世帯住宅には「完全分離型」「部分共有型」「同居型（完全同居）」の3種類があります。それぞれのメリット・デメリットを比較して、家族に合うタイプを選びましょう。\n\n完全分離型はキッチン・浴室・玄関もすべて別々です。プライバシーが最も高く、将来的に賃貸に出すことも可能ですが建築費が高くなります（4,000〜6,000万円程度）。部分共有型は費用を抑えつつ交流もできますが、生活リズムの違いが摩擦になることがあります。完全同居型は費用は最も安いですが、プライバシーが確保しにくいです。\n\nどのタイプを選ぶかは「関係性の近さ」「費用」「将来的な使い方」によって変わります。建築前に生活スタイルをよく話し合うことが成功の鍵です。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    3: { title: "同居前に決めておくべきお金のルール", body: "同居を始めてからお金のことでもめるケースは非常に多いです。事前にルールを決めておくことで、こうしたトラブルを未然に防ぐことができます。\n\n決めておくべきお金のルールは5つです。①光熱費の負担割合②食費の負担③修繕費の負担④介護費用の見通し⑤固定資産税・ローンの負担です。\n\nこれらは「なんとなく」で進めてしまうと後からトラブルになります。できれば書面（合意書）に残しておくことをおすすめします。FPに同席してもらうことで、客観的に整理しやすくなります。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    4: { title: "義親との同居を成功させるポイント", body: "配偶者の親（義父母）との同居は、実の親との同居と比べてより慎重な準備が必要です。価値観・生活習慣の違いが表面化しやすく、パートナーとの連携が特に重要です。\n\n事前に確認すべきことは「食事のスタイル（和食中心か・食事時間・好き嫌い）」「来客対応」「育児・孫への関わり方（どの程度干渉するか）」「趣味・生活音への許容度」です。\n\n最も重要なのは「パートナーとの連携」です。問題が起きたとき、配偶者が自分の親をかばいすぎると関係が壊れます。「家族として一緒に解決する」というスタンスを事前に確認しておきましょう。また同居前に「うまくいかなかった場合の出口」も話し合っておくことで、精神的な安心感が生まれます。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    5: { title: "親との近居のメリットと補助金", body: "完全同居ではなく「近居（近くに住む）」という選択肢が近年注目されています。適度な距離感を保ちながら支え合えるスタイルです。\n\n近居のメリットは「緊急時に駆けつけやすい」「孫と親の交流が増える」「お互いのプライバシーを守れる」「介護が必要になったときに対応しやすい」点です。同居のような生活上のストレスが少ないため、関係が良好に保たれやすいとも言われています。\n\nまた「近居」を支援する自治体の補助金もあります。東京都や各市区町村の「近居・同居促進助成金」などがあり、引っ越し費用や家賃補助として数万〜数十万円が支援されることがあります。「ちょうどいい距離感」を実現する選択肢として検討してみましょう。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    6: { title: "二世帯住宅リフォームの費用相場", body: "既存の実家を二世帯住宅にリフォームする場合、どれくらいの費用がかかるのかを事前に把握しておきましょう。\n\nリフォームの費用は「どこまで改装するか」によって大きく変わります。玄関を分けるだけの軽微なリフォームで200〜500万円、水回りを増設する部分共有型で500〜1,000万円、完全分離型への改装で1,000〜2,500万円程度が目安です。\n\n利用できる補助金として「長期優良住宅化リフォーム推進事業（国）」「介護リフォーム補助金（介護保険）」「耐震改修補助金（自治体）」などがあります。費用が大きいため、複数のリフォーム会社から見積もりを取り、内容を比較したうえで判断することをおすすめします。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    7: { title: "同居解消・別居の進め方", body: "同居を始めたものの、うまくいかずに別居を検討する方もいます。別居を決断するときの進め方と、感情的にならないための工夫を紹介します。\n\n別居の主なきっかけは「生活習慣・価値観の違い」「プライバシーの侵害感」「配偶者と親の関係悪化」「介護負担の偏り」などです。こじれる前に「定期的な話し合いの場」を持つことで、問題を小さいうちに解決することが大切です。\n\n別居を進める際は感情的にならず「お互いにとってより良い選択」として伝えることが重要です。不動産会社に相談することで、新居探しと並行して実家の活用方法（賃貸・売却）も検討できます。別居は「失敗」ではなく「より良い関係のための選択」として前向きに捉えましょう。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    8: { title: "介護が必要になったときの同居対応", body: "同居している親の要介護度が上がると、住まいの環境整備が必要になります。バリアフリーリフォームを適切に行うことで、安全に在宅介護ができる環境を作りましょう。\n\nバリアフリーリフォームの主な内容は「手すりの設置（浴室・トイレ・廊下・階段）」「段差の解消」「滑り止め床材への変更」「浴室の改修」「ドアを引き戸に変更（車椅子対応）」などです。\n\n費用の一部は「介護保険の住宅改修費」として最大20万円（1割負担）の支給を受けられます。リフォームは要介護認定後に行うのが助成金活用の条件になることが多いため、まずはケアマネジャーに相談してから進めることをおすすめします。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    9: { title: "二世帯住宅の相続税節税効果", body: "二世帯住宅に親と一緒に住んでいる場合、相続時に「小規模宅地等の特例」が適用できる可能性があります。この特例を使うと、土地の評価額が最大80%減額されるため、相続税が大幅に軽減されます。\n\n適用条件の主なものは「被相続人（亡くなった親）が所有していた土地」「相続人が同居の親族（配偶者または子供）」「申告期限まで売却しないこと」などです。二世帯住宅の場合、完全分離型でも2024年以降は同居と認められ特例が適用されることが明確化されました。\n\n適用できる面積は最大330㎡で、評価額が80%減額されます。例えば土地評価5,000万円の場合、特例適用後は1,000万円として計算されます。この特例の有無で相続税が数百万〜数千万円変わることもあります。必ず相続に詳しい税理士に確認してから対策を取りましょう。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] },
    10: { title: "実家への引っ越し準備チェックリスト", body: "実家に引っ越す（Uターン同居）準備は早めに始めることが重要です。手続き・荷物整理・近隣への挨拶など、やることは意外と多くあります。\n\n引っ越し前の主な手続きは「住民票の異動」「運転免許証の住所変更」「マイナンバーカードの住所変更」「金融機関・保険の住所変更」「郵便物の転送手続き（郵便局）」です。子どもがいる場合は「転校手続き・保育園の変更」も必要です。\n\n荷物整理は余裕をもって進めましょう。実家にある親の荷物と自分の荷物が混在するため、事前に「何を残すか・処分するか」を親と一緒に確認することが重要です。近隣への挨拶は引っ越し当日か翌日に行うのが基本です。実家のご近所への挨拶は良好な地域関係の第一歩になります。", a8: [{name: "相続の窓口", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+C8KT7E+56AO+BWVTE", desc: "相続・不動産をワンストップで解決。"}, {name: "ミライアス（リースバック）", url: "https://px.a8.net/svt/ejp?a8mat=4B3VR7+BMJRTM+4I6M+5YJRM", desc: "実家を現金化して近居費用に充てる選択肢も。"}] }
  }
}

