export async function generateMetadata({ params }: { params: Promise<{ category: string; id: string }> }): Promise<Metadata> {
  const { category, id } = await params
  const col = COLUMNS[category]?.[Number(id)]
  if (!col) return { title: '記事が見つかりません | 実家どうするナビ' }
  return {
    title: col.title + ' | 実家どうするナビ',
    description: col.body.substring(0, 80).replace(/\\n/g, ''),
  }
}

export default async function ColumnPage({ params }: { params: Promise<{ category: string; id: string }> }) {
  const { category, id } = await params
  const col = COLUMNS[category]?.[Number(id)]
  if (!col) notFound()
  const catLabel = CAT_LABEL[category] || ''
  const idNum = Number(id)
  const paragraphs = col.body.split('\\n\\n').filter(Boolean)
  return (
    <main style={{ maxWidth: 480, margin: '0 auto', padding: '16px 16px 48px' }}>
      <div style={{ marginBottom: 16 }}>
        <Link href="/column" style={{ fontSize: 12, color: '#6b7280', textDecoration: 'none' }}>← コラム一覧</Link>
        <p style={{ fontSize: 11, color: '#2d6a2d', fontWeight: 600, margin: '8px 0 4px' }}>{catLabel}</p>
        <h1 style={{ fontSize: 18, fontWeight: 700, color: '#1f2937', lineHeight: 1.5 }}>{col.title}</h1>
      </div>
      <div style={{ background: '#fff', border: '0.5px solid #e5e7eb', borderRadius: 12, padding: '16px', marginBottom: 16 }}>
        {paragraphs.map((p, i) => (
          <p key={i} style={{ fontSize: 14, color: '#374151', lineHeight: 1.8, margin: i < paragraphs.length - 1 ? '0 0 14px' : '0' }}>{p}</p>
        ))}
      </div>
      {col.a8.length > 0 && (
        <div style={{ marginBottom: 16 }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 10 }}>
            <div style={{ width: 28, height: 28, borderRadius: '50%', overflow: 'hidden', flexShrink: 0, position: 'relative', border: '2px solid #90c890' }}>
              <img src="/images/characters/minori-smile.png" alt="みのり" width={28} height={28} style={{ objectFit: 'cover' }} />
            </div>
            <p style={{ fontSize: 12, fontWeight: 700, color: '#1a2d1a', margin: 0 }}>
              この記事に関連するサービス
            </p>
          </div>
          <p style={{ fontSize: 11, color: '#9ca3af', marginBottom: 8 }}>※ 広告・PR</p>
          {col.a8.map((s, i) => {
            // 固定紹介ページがある場合はそちらへ、なければ直接リンク
            const linkUrl = s.serviceSlug ? `/service/${s.serviceSlug}` : s.url
            const isInternal = !!s.serviceSlug
            return (
              <div key={i} style={{ background: '#fff', border: '1px solid #b8ddb8', borderRadius: 12, overflow: 'hidden', marginBottom: 10 }}>
                {/* バナー画像 */}
                {s.imgUrl && (
                  <div style={{ textAlign: 'center', padding: '10px 12px 0', background: '#f9fbf9' }}>
                    <img
                      src={s.imgUrl}
                      alt={s.name}
                      width={Math.min(s.imgWidth ?? 300, 260)}
                      style={{ maxWidth: '100%', maxHeight: 160, objectFit: 'contain', borderRadius: 6 }}
                    />
                  </div>
                )}
                <div style={{ padding: '10px 12px 12px' }}>
                  <div style={{ fontSize: 13, fontWeight: 700, color: '#1f2937', marginBottom: 4 }}>{s.name}</div>
                  <div style={{ fontSize: 12, color: '#6b7280', marginBottom: 6, lineHeight: 1.5 }}>{s.desc}</div>
                  {/* 深掘りコラムへのリンク（あれば） */}
                  {s.deepColumnUrl && (
                    <Link href={s.deepColumnUrl}
                      style={{ display: 'block', background: '#f0faf0', border: '1px solid #b8ddb8', borderRadius: 6, padding: '7px', textAlign: 'center' as const, fontSize: 11, fontWeight: 600, color: '#1a5a1a', textDecoration: 'none', marginBottom: 6 }}>
                      📖 このサービスを詳しく読む →
                    </Link>
                  )}
                  {/* サービス紹介ページ or 直接リンク */}
                  {isInternal ? (
                    <Link href={linkUrl}
                      style={{ display: 'block', background: 'linear-gradient(135deg, #2d6a2d, #1a5a1a)', color: '#fff', borderRadius: 6, padding: '8px', textAlign: 'center' as const, fontSize: 12, fontWeight: 700, textDecoration: 'none' }}>
                      サービスの詳細を見る →
                    </Link>
                  ) : (
                    <a href={s.url} target="_blank" rel="nofollow noopener noreferrer"
                      style={{ display: 'block', background: 'linear-gradient(135deg, #2d6a2d, #1a5a1a)', color: '#fff', borderRadius: 6, padding: '8px', textAlign: 'center' as const, fontSize: 12, fontWeight: 700, textDecoration: 'none' }}>
                      詳しく見てみる →
                    </a>
                  )}
                </div>
                {/* インプレッション計測 */}
                {s.impUrl && (
                  <img src={s.impUrl} width={1} height={1} style={{ border: 'none', display: 'block' }} loading="lazy" alt="" />
                )}
              </div>
            )
          })}
        </div>
      )}
      <div style={{ display: 'flex', gap: 8, marginBottom: 16 }}>
        {idNum > 1 && <Link href={`/column/${category}/${idNum - 1}`} style={{ flex: 1, display: 'block', textAlign: 'center' as const, background: '#fff', border: '0.5px solid #e5e7eb', borderRadius: 8, padding: '10px', fontSize: 13, color: '#374151', textDecoration: 'none' }}>← 前の記事</Link>}
        {idNum < 10 && <Link href={`/column/${category}/${idNum + 1}`} style={{ flex: 1, display: 'block', textAlign: 'center' as const, background: '#fff', border: '0.5px solid #e5e7eb', borderRadius: 8, padding: '10px', fontSize: 13, color: '#374151', textDecoration: 'none' }}>次の記事 →</Link>}
      </div>
      <Link href="/" style={{ display: 'block', textAlign: 'center' as const, background: '#1a3d1a', color: '#b8ddb8', borderRadius: 8, padding: '12px', fontSize: 13, fontWeight: 600, textDecoration: 'none' }}>
        診断を受ける →
      </Link>
    </main>
  )
}
